package analyze

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// dataflowFixture builds a small project exercising every dataflow
// site kind: a slice with an initializer, an append in a second
// file, an index write, a hand-off to a mutating helper, a map
// delete, a cross-package selector append, struct fields set both
// by literal and by assignment, an ambiguous field name, a local,
// and a generated file that must be skipped.
func dataflowFixture(t *testing.T) *Project {
	t.Helper()
	dir := t.TempDir()
	write := func(rel, src string) {
		full := filepath.Join(dir, rel)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(full, []byte(src), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	write("go.mod", "module example.com/dflow\n\ngo 1.21\n")
	write("store/store.go", `package store

var Items []string = []string{"a", "b"}

var Limit = 10

var Seen map[string]bool = map[string]bool{}

func Reset() {
	Items[0] = "z"
}

func Reload() {
	Items = load()
}

func load() []string {
	return []string{"x"}
}

func Touch() {
	Mutate(Items)
}

func Mutate(s []string) {
	s[0] = "q"
}
`)
	write("store/more.go", `package store

func Add(s string) {
	Items = append(Items, s)
}

func Bump() {
	Limit = 20
}

func Forget(k string) {
	delete(Seen, k)
}
`)
	write("store/gen.go", `// Code generated by fixture. DO NOT EDIT.

package store

var GenItems []string

func Regen() {
	GenItems = append(GenItems, "g")
}
`)
	write("config/config.go", `package config

type Config struct {
	Names []string
	Level int
}

type Basket struct {
	Hits map[string]int
}

func NewBasket() *Basket {
	return &Basket{Hits: make(map[string]int)}
}

func (b *Basket) Hit(name string) {
	b.Hits[name]++
}
`)
	write("other/other.go", `package other

type Other struct {
	Names []string
}
`)
	write("main.go", `package main

import (
	"example.com/dflow/config"
	"example.com/dflow/store"
)

var cfg = config.Config{Names: []string{"n1"}}

func main() {
	c := config.Config{}
	c.Names = []string{"a"}
	c.Level = compute()
	scratch := []string{"s"}
	scratch = append(scratch, "t")
	_ = c
	_ = scratch
}

func compute() int { return 7 }

func extra() {
	store.Items = append(store.Items, "cross")
}
`)
	p, err := Analyze(dir)
	if err != nil {
		t.Fatalf("Analyze: %v", err)
	}
	return p
}

func mustContain(t *testing.T, label, out string, subs ...string) {
	t.Helper()
	for _, s := range subs {
		if !strings.Contains(out, s) {
			t.Errorf("%s: answer missing %q\n---\n%s", label, s, out)
		}
	}
}

// The slice: declaration, initializer, reassignment from a call,
// append in another file, index write, honest hand-off label, and
// a cross-package append — all four question shapes route here.
func TestDataflowSlice(t *testing.T) {
	p := dataflowFixture(t)
	for _, q := range []string{
		"where does Items get its data",
		"where does Items come from",
		"where does Items change",
		"what changes Items",
	} {
		out, ok := p.Answer(q)
		if !ok {
			t.Fatalf("Answer(%q) not handled", q)
		}
		mustContain(t, q, out,
			"`Items`",
			"a slice — a growable list — of type []string",
			"a package-level variable in package store",
			"store/store.go",
			"the return value of load()",
			"store/more.go",
			"new items are added with",
			"element [0] is set to",
			"passed to store.Mutate",
			"that function can change its contents",
			"main.go",
		)
	}
}

// A plain package var: initializer plus a reassignment elsewhere.
func TestDataflowVarReassigned(t *testing.T) {
	p := dataflowFixture(t)
	out, ok := p.DataflowText("Limit")
	if !ok {
		t.Fatal("DataflowText(Limit) not ok")
	}
	mustContain(t, "Limit", out,
		"`Limit`",
		"starts as 10",
		"set from the literal 20",
		"store/more.go",
	)
}

// A map: delete() is a change site.
func TestDataflowMapDelete(t *testing.T) {
	p := dataflowFixture(t)
	out, ok := p.DataflowText("Seen")
	if !ok {
		t.Fatal("DataflowText(Seen) not ok")
	}
	mustContain(t, "Seen", out,
		"`Seen`",
		"a map — a lookup table — of type map[string]bool",
		"an entry is deleted",
		"store/more.go",
	)
}

// Struct fields: qualified names resolve; a field gets data from a
// composite literal at package level and from plain assignments.
func TestDataflowFields(t *testing.T) {
	p := dataflowFixture(t)
	out, ok := p.DataflowText("Config.Names")
	if !ok {
		t.Fatal("DataflowText(Config.Names) not ok")
	}
	mustContain(t, "Config.Names", out,
		"a field of the Config struct (package config)",
		"config/config.go",
		"main.go",
		"[]string{\"n1\"}",
		"[]string{\"a\"}",
	)
	out, ok = p.DataflowText("Config.Level")
	if !ok {
		t.Fatal("DataflowText(Config.Level) not ok")
	}
	mustContain(t, "Config.Level", out,
		"the return value of compute()",
		"main.go",
	)
}

// A field element bumped through a method receiver (b.Hits[name]++)
// is a change site, and a make() inside a composite literal is told
// without doubling the word make.
func TestDataflowFieldIndexIncDec(t *testing.T) {
	p := dataflowFixture(t)
	out, ok := p.DataflowText("Basket.Hits")
	if !ok {
		t.Fatal("DataflowText(Basket.Hits) not ok")
	}
	mustContain(t, "Basket.Hits", out,
		"a field of the Basket struct (package config)",
		"element [name] is increased by one (++)",
		"a fresh empty value from make(map[string]int)",
		"config/config.go",
	)
	if strings.Contains(out, "make(make(") {
		t.Errorf("doubled make in answer:\n%s", out)
	}
	if strings.Contains(out, "never edited in place") {
		t.Errorf("answer claims no in-place edits but the ++ site exists:\n%s", out)
	}
}

// A bare field name shared by two structs is ambiguous — the
// answer lists the candidates instead of guessing.
func TestDataflowAmbiguous(t *testing.T) {
	p := dataflowFixture(t)
	out, ok := p.DataflowText("Names")
	if !ok {
		t.Fatal("DataflowText(Names) not ok")
	}
	mustContain(t, "Names", out,
		"could mean more than one thing",
		"Config",
		"Other",
	)
}

// A local is answered inside its function, with the scope said out
// loud.
func TestDataflowLocal(t *testing.T) {
	p := dataflowFixture(t)
	out, ok := p.DataflowText("scratch")
	if !ok {
		t.Fatal("DataflowText(scratch) not ok")
	}
	mustContain(t, "scratch", out,
		"a local variable inside main.main",
		"It only lives while main runs",
		"new items are added with",
	)
}

// Unknown names fall through (ok=false) so other brains can try;
// a near miss gets the did-you-mean answer, never a guess.
func TestDataflowNotFound(t *testing.T) {
	p := dataflowFixture(t)
	if out, ok := p.DataflowText("Zanzibar"); ok {
		t.Errorf("DataflowText(Zanzibar) = ok with %q, want fall-through", out)
	}
	out, ok := p.DataflowText("Itms")
	if !ok {
		t.Fatal("DataflowText(Itms) should offer a did-you-mean")
	}
	mustContain(t, "Itms", out, "Did you mean", "Items")
	if _, ok := p.Answer("where does the water come from"); ok {
		t.Error("Answer stole a non-code question about water")
	}
}

// Generated files are skipped entirely: their vars are not tracked.
func TestDataflowSkipsGenerated(t *testing.T) {
	p := dataflowFixture(t)
	if p.HasData("GenItems") {
		t.Error("generated-file var GenItems should not be tracked")
	}
	if !p.HasData("Items") || !p.HasData("Config.Names") || !p.HasData("scratch") {
		t.Error("HasData should find the tracked var, field, and local")
	}
}

// The question shapes are codebase questions, so a fresh chat
// auto-analyzes the project for them.
func TestDataflowIsCodebaseQuestion(t *testing.T) {
	for _, q := range []string{
		"where does Items get its data",
		"where does Items come from",
		"where does Items change",
		"what changes Items",
	} {
		if !IsCodebaseQuestion(q) {
			t.Errorf("IsCodebaseQuestion(%q) = false, want true", q)
		}
	}
}
